    {
      "name": "Power Rule",
      "aliases": ["power rule", "幂法则"],
      "definition_snippet": "If f(x) = x^n where n is a real number, then f'(x) = nx^(n-1).",
      "category": "theorem"
    },
    {
      "name": "Derivative",
      "aliases": ["derivative", "导数"],
      "definition_snippet": "The rate of change of a function, denoted f'(x).",
      "category": "operation"
    },
    {
      "name": "Real exponent",
      "aliases": ["real exponent", "实数指数"],
      "definition_snippet": "An exponent n that may be any real number, such as 1/2, -3, or π.",
      "category": "concept"
    },
    {
      "name": "Constant Multiple Rule",
      "aliases": ["constant multiple rule", "常数倍法则"],
      "definition_snippet": "If c is constant and f is differentiable, then d/dx[cf(x)] = cf'(x).",
      "category": "theorem"
    },
    {
      "name": "Sum Rule",
      "aliases": ["sum rule", "和法则"],
      "definition_snippet": "If f and g are differentiable, then d/dx[f(x) + g(x)] = f'(x) + g'(x).",
      "category": "theorem"
    },
    {
      "name": "Difference Rule",
      "aliases": ["difference rule", "差法则"],
      "definition_snippet": "If f and g are differentiable, then d/dx[f(x) - g(x)] = f'(x) - g'(x).",
      "category": "theorem"
    },
    {
      "name": "Differentiability",
      "aliases": ["differentiable function", "可微性"],
      "definition_snippet": "The property that a function has a derivative at the relevant point.",
      "category": "property"
    },
    {
      "name": "Polynomial function",
      "aliases": ["polynomial", "多项式函数"],
      "definition_snippet": "A function formed from powers of x with constant coefficients.",
      "category": "concept"
    },
    {
      "name": "Exponential function",
      "aliases": ["exponential function", "指数函数"],
      "definition_snippet": "A function in which the variable appears in the exponent.",
      "category": "concept"
    },
    {
      "name": "Natural exponential function e^x",
      "aliases": ["e^x", "自然指数函数"],
      "definition_snippet": "The exponential function with base e; its derivative is itself.",
      "category": "concept"
    },
    {
      "name": "General exponential function a^x",
      "aliases": ["a^x", "一般指数函数"],
      "definition_snippet": "An exponential function with base a; its derivative is a^x ln a.",
      "category": "concept"
    },
    {
      "name": "Number e",
      "aliases": ["Euler's number", "自然常数 e"],
      "definition_snippet": "The unique number for which lim_{h→0} (e^h - 1)/h = 1.",
      "category": "concept"
    },
    {
      "name": "Natural logarithm",
      "aliases": ["ln", "自然对数"],
      "definition_snippet": "The logarithm with base e, appearing in d/dx(a^x) = a^x ln a.",
      "category": "concept"
    },
    {
      "name": "Limit",
      "aliases": ["limit", "极限"],
      "definition_snippet": "A value approached by a function as its input approaches some point.",
      "category": "concept"
    },
    {
      "name": "Position function",
      "aliases": ["position", "位置函数"],
      "definition_snippet": "A function s(t) giving the position of an object over time.",
      "category": "concept"
    },
    {
      "name": "Velocity",
      "aliases": ["velocity", "速度"],
      "definition_snippet": "The derivative of position: v(t) = s'(t).",
      "category": "concept"
    },
    {
      "name": "Acceleration",
      "aliases": ["acceleration", "加速度"],
      "definition_snippet": "The derivative of velocity: a(t) = v'(t) = s''(t).",
      "category": "concept"
    },
    {
      "name": "Second derivative",
      "aliases": ["second derivative", "二阶导数"],
      "definition_snippet": "The derivative of the derivative, written f''(x) or s''(t).",
      "category": "operation"
    },
    {
      "name": "Cost function",
      "aliases": ["cost function", "成本函数"],
      "definition_snippet": "A function C(x) representing cost as a function of quantity.",
      "category": "concept"
    },
    {
      "name": "Marginal cost",
      "aliases": ["marginal cost", "边际成本"],
      "definition_snippet": "The derivative of the cost function: MC = C'(x).",
      "category": "concept"
    },
    {
      "name": "Rate of change",
      "aliases": ["rate of change", "变化率"],
      "definition_snippet": "A quantity describing how one variable changes relative to another.",
      "category": "concept"
    },
    {
      "name": "Tangent line approximation",
      "aliases": ["linear approximation", "切线近似"],
      "definition_snippet": "Uses the derivative to estimate function values near a known point.",
      "category": "operation"
    },
    {
      "name": "Differentiation",
      "aliases": ["differentiation", "求导"],
